"use client";

import FlightConfirmationModal from "./flight-confirmation-modal";
import { useFlightConfirmation } from "@/context/FlightConfirmationContext";

export default function GlobalFlightConfirmation() {
  const {
    flightConfirmation,
    hideFlightConfirmation,
  } = useFlightConfirmation();

  if (!flightConfirmation.open) return null;

  return (
    <FlightConfirmationModal
      droneId={flightConfirmation.droneId}
      onConfirm={hideFlightConfirmation}
    />
  );
}